CREATE DATABASE IF NOT EXISTS kfc_streams; USE kfc_streams;
CREATE TABLE users(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120),email VARCHAR(190) UNIQUE,password_hash VARCHAR(255),role ENUM('user','admin') DEFAULT 'user',verified_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE leagues(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(160),country VARCHAR(120),logo_url VARCHAR(255));
CREATE TABLE competitions(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(160),league_id BIGINT,season VARCHAR(20),FOREIGN KEY(league_id) REFERENCES leagues(id));
CREATE TABLE teams(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(160),country VARCHAR(120),logo_url VARCHAR(255),league_id BIGINT,FOREIGN KEY(league_id) REFERENCES leagues(id));
CREATE TABLE players(id BIGINT PRIMARY KEY AUTO_INCREMENT,team_id BIGINT,name VARCHAR(160),position VARCHAR(60),shirt_number INT,photo_url VARCHAR(255),FOREIGN KEY(team_id) REFERENCES teams(id));
CREATE TABLE matches(id BIGINT PRIMARY KEY AUTO_INCREMENT,competition_id BIGINT,home_team_id BIGINT,away_team_id BIGINT,kickoff_at DATETIME,status VARCHAR(40),home_score INT DEFAULT 0,away_score INT DEFAULT 0,FOREIGN KEY(competition_id) REFERENCES competitions(id));
CREATE TABLE streams(id BIGINT PRIMARY KEY AUTO_INCREMENT,match_id BIGINT,hls_url VARCHAR(500),drm_policy JSON,active BOOLEAN DEFAULT TRUE,FOREIGN KEY(match_id) REFERENCES matches(id));
CREATE TABLE subscriptions(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT,plan VARCHAR(50),status VARCHAR(50),starts_at DATETIME,ends_at DATETIME,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE payments(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT,provider VARCHAR(40),amount DECIMAL(10,2),currency CHAR(3),status VARCHAR(40),reference VARCHAR(190),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notifications(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT,title VARCHAR(190),body TEXT,read_at DATETIME);
CREATE TABLE watch_history(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT,match_id BIGINT,progress_seconds INT,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE favorites(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT,match_id BIGINT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE advertisements(id BIGINT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(190),placement VARCHAR(80),asset_url VARCHAR(255),target_url VARCHAR(255),active BOOLEAN DEFAULT TRUE);
CREATE TABLE comments(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT,match_id BIGINT,body TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE chat_messages(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT,match_id BIGINT,body TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
